solution.solution.rs:
use std::future::Future;
use std::pin::{pin, Pin};
use std::task::{Context, Poll, Waker};

struct YieldNow {
    remaining: u32,
}

impl YieldNow {
    fn new(times: u32) -> Self {
        YieldNow { remaining: times }
    }
}

impl Future for YieldNow {
    type Output = ();
    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        if self.remaining == 0 {
            return Poll::Ready(());
        }
        self.remaining -= 1;
        cx.waker().wake_by_ref();
        Poll::Pending
    }
}

async fn add_slowly(a: u32, b: u32) -> u32 {
    YieldNow::new(2).await;
    a + b
}

async fn sum_all(values: Vec<u32>) -> u32 {
    let mut total = 0;
    for v in values {
        total = add_slowly(total, v).await;
    }
    total
}

fn run<F: Future>(future: F) -> (F::Output, u32) {
    let mut future = pin!(future);
    let mut cx = Context::from_waker(Waker::noop());
    let mut polls = 0;
    loop {
        polls += 1;
        if let Poll::Ready(value) = future.as_mut().poll(&mut cx) {
            return (value, polls);
        }
    }
}

hints:
The standard library defines the trait and its result like this (you implement `poll`, and an executor calls it):

```rust-norun
trait Future {
    type Output;
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output>;
}
enum Poll<T> { Ready(T), Pending }
```

In `run`, `let mut future = pin!(future);` gives a `Pin<&mut F>`; each time round the loop call `future.as_mut().poll(&mut cx)` (`as_mut` reborrows the pin, so it can be polled again), with `let mut cx = Context::from_waker(Waker::noop());` made once before the loop.

unitTests:
test("a future that yields", || {
    check_eq(run(YieldNow::new(0)), ((), 1));
    check_eq(run(YieldNow::new(4)), ((), 5));
});

test("async functions are futures", || {
    check_eq(run(add_slowly(2, 3)), (5, 3));
    check_eq(run(async { 42 }), (42, 1));
});

test("awaiting in a loop", || {
    check_eq(run(sum_all(vec![1, 2, 3, 4])), (10, 9));
    check_eq(run(sum_all(vec![])), (0, 1));
});

test("futures are lazy", || {
    let mut started = false;
    let fut = async { started = true; 7 };
    let (value, _) = run(fut);
    check_eq(value, 7);
    check(started);
});

